// keeps its real 8-bit anti-aliased coverage mask. Loaded at draw time via
// LovyanGFX's canvas.loadFont(data) (see DistanceIndicator.cpp,
// NavigationScreen.cpp) - VLWfont blends glyph edges against the color
// passed to setTextColor()'s background argument directly, not a
// destination readback, so it renders correctly on this write-only panel
// without the workaround AntiAlias.h needed for shapes.

